(window.LADDER_CARDS=window.LADDER_CARDS||{})["18·logi2"]=[{"q": "A linear program in which some variables must be whole numbers. What is it called?", "a": "an integer program", "w": ["a linear relaxation", "a quadratic program", "a transportation problem"], "why": "Crates, trucks and people come whole."}, {"q": "The same program with the wholeness requirement dropped. What is it called?", "a": "its linear relaxation", "w": ["its dual", "its integer hull", "its feasible set"], "why": "Its best value bounds every whole plan."}, {"q": "For a maximising integer program, how does the relaxation’s best value compare with the best whole value?", "a": "it is at least as large", "w": ["it is smaller", "it is equal, always", "it has no relation"], "why": "Every whole plan lies in the relaxed region."}, {"q": "Rounding the relaxation’s best corner to the nearest whole point. What can go wrong?", "a": "it can break a limit, or be far from the best whole plan", "w": ["nothing: it is always best", "it always lowers the value by 1", "it can only raise the value"], "why": "The best whole plan can lie away from the corner."}, {"q": "Splitting the region on a fractional variable and dropping parts by their bounds. What is the method called?", "a": "branch and bound", "w": ["the simplex method", "dynamic programming", "gradient descent"], "why": "Land and Doig, 1960."}, {"q": "The relaxation gives y = 2.6. How should the region be split?", "a": "y ≤ 2 and y ≥ 3", "w": ["y ≤ 2.6 and y ≥ 2.6", "y ≤ 2.5 and y ≥ 2.5", "y = 2 and y = 3 only"], "why": "No whole number lies strictly between 2 and 3, so the corner is cut away."}, {"q": "A branch’s bound is 17, and a whole plan worth 19 is in hand. What is done with the branch (maximising)?", "a": "it is pruned: no plan inside can win", "w": ["it is split again", "its corner is rounded", "it replaces the plan in hand"], "why": "Its ceiling is below the best found."}, {"q": "Fifty yes-or-no choices. Roughly how many plans would listing check?", "a": "about 10¹⁵", "w": ["about 100", "about 2500", "about 10⁵⁰"], "why": "2⁵⁰ > (10³)⁵."}, {"q": "Why does finding a good whole plan early speed up branch and bound?", "a": "more branches have bounds below it and are pruned", "w": ["it makes the relaxation exact", "it removes the need for bounds", "it shrinks the region"], "why": "Start from a rounded-down plan."}, {"q": "How hard are integer programs in general?", "a": "NP-hard: no method known is quick on every one", "w": ["always solvable quickly by simplex", "impossible to solve", "as easy as linear programs"], "why": "In practice branch and bound often finishes fast."}];
