(window.LADDER_CARDS=window.LADDER_CARDS||{})["24·logi"]=[{"q": "Order swings that grow larger at each stage up a supply chain. What is this called?", "a": "the bullwhip effect", "w": ["the ripple effect", "economies of scale", "the stockout effect"], "why": "Also called the Forrester effect."}, {"q": "Who first showed swings growing up a chain, in Industrial Dynamics (1961)?", "a": "Jay Forrester", "w": ["Frederick Taylor", "W. Edwards Deming", "Taiichi Ohno"], "why": "System dynamics at MIT."}, {"q": "Each period, order enough to bring stock on hand and on order back up to a target. What is this policy called?", "a": "an order-up-to policy", "w": ["an economic order quantity", "a just-in-time kanban", "a fixed-period batch"], "why": "The target is the order-up-to level."}, {"q": "Forecast = last week’s sales; target = 3 weeks of forecast. Sales rise for good from 20 to 24. What is ordered in the week of the rise?", "a": "36", "w": ["24", "28", "32"], "why": "24 + 3 · 4: replace sales and raise the target."}, {"q": "Same chain, the week after the rise, sales still 24. What is ordered?", "a": "24", "w": ["36", "20", "12"], "why": "The target no longer moves: replacement only."}, {"q": "A classroom game with four stages that lets players feel order swings grow. What is it called?", "a": "the beer distribution game", "w": ["the prisoner’s dilemma", "the newsvendor game", "the travelling salesman game"], "why": "Developed at MIT in the 1960s."}, {"q": "Which is one of the four causes of the bullwhip effect named by Lee, Padmanabhan and Whang (1997)?", "a": "order batching", "w": ["sharing point-of-sale data", "shorter lead times", "everyday low prices"], "why": "Also demand forecast updating, price swings, rationing games."}, {"q": "Which remedy lets upstream stages forecast from true customer demand?", "a": "sharing point-of-sale data", "w": ["larger order batches", "longer lead times", "more price promotions"], "why": "Information sharing."}, {"q": "A forecast smoothed with time constant τ replaces last week’s sales. How tall is the jump in orders after a step in demand?", "a": "about 1/τ as tall", "w": ["about τ times as tall", "the same", "twice as tall"], "why": "The order is demand plus the target’s rate of change."}, {"q": "Target stock = k weeks of forecast; sales rise for good by d. How far above the new sales level is the order in the week of the rise?", "a": "k·d", "w": ["d", "d/k", "k + d"], "why": "Cutting lead time cuts k, and so the jump."}];
